  # Renders an inline SVG icon. `name` is a symbol/string key in ICON_PATHS
  # (dashes and dots are normalized to underscores). Extra HTML options are
  # passed through to the <svg> tag; `class:` defaults to `size-5`.
  def heroicon(name, class: 'size-5', **options)
    key = name.to_s.tr('-. ', '___').to_sym
    inner = ICON_PATHS[key]
    if inner.nil?
      raise ArgumentError, "Unknown icon #{name.inspect}" if Rails.env.local?

      return ''.html_safe
    end

    css = binding.local_variable_get(:class)
    content_tag(:svg, inner.html_safe,
                { class: css, viewBox: '0 0 24 24', fill: 'none',
                  stroke: 'currentColor', 'stroke-width': 1.5,
                  'aria-hidden': true, 'stroke-linecap': 'round',
                  'stroke-linejoin': 'round' }.merge(options))
  end
